.local/hermes-lab/venv/bin/python - <<'PY'
import importlib.util, json, tempfile, sys
from pathlib import Path
from copy import deepcopy
sys.dont_write_bytecode=True
spec=importlib.util.spec_from_file_location('verify_live', 'verification/poc_profile_context/verify_live.py')
v=importlib.util.module_from_spec(spec); spec.loader.exec_module(v)
with tempfile.TemporaryDirectory(prefix='clanker-verifier-check-') as tmp:
 e=Path(tmp); prompt='Return only your synthetic memory token.'
 tasks=[]; submitted={'workspace_id':'TEAM','channel_id':'CHANNEL','tasks':[]}; results={'tasks':[]}; receipts={}
 for i,key in enumerate(('A','B')):
  token='CLANKER_DUMMY_'+key*32; profile='fixture-'+key.lower(); home=str(e/profile); sid='SESSION_'+key; root=str(100+i); memory='Fixture '+token
  tasks.append({'key':key,'sender_id':'USER_'+key,'profile':profile,'profile_home':home,'token':token,'memory_file_sha256':v.digest(memory),'receipts':key+'-events.jsonl'})
  submitted['tasks'].append({'key':key,'user':'USER_'+key,'ts':root,'text':'<@BOT> '+prompt})
  results['tasks'].append({'key':key,'root_ts':root,'final_reply':{'user':'BOT','ts':str(120+i),'thread_ts':root,'text':token}})
  common={'pid':999,'profile':profile,'context_profile':profile,'profile_home':home,'session_id':sid,'task_id':sid,'context_session_id':sid,'user_id':'USER_'+key,'chat_id':'CHANNEL','slack_thread_id':root,'workspace_id':'TEAM','platform':'slack'}
