def probe_hashes(value):
    text = value if isinstance(value, str) else json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)
    return sorted({digest(match.group(0)) for match in PROBE.finditer(text)})


def argument_observation(tool_name, args):
    """Only bounded session_search selectors are readable; every other argument is hash-only."""
    safe = {}
    truncated = []
    if tool_name == "session_search" and isinstance(args, dict):
        limits = {"query": 1024, "profile": 128, "session_id": 128, "role_filter": 64,
                  "sort": 32, "detail": 32, "after": 64, "before": 64}
        for key, limit in limits.items():
            if key in args and isinstance(args[key], str):
                value = PROBE.sub(lambda match: "[probe_sha256:" + digest(match.group(0)) + "]", args[key])
                safe[key] = value[:limit]
                if len(value) > limit:
                    truncated.append(key)
        for key in ("limit", "window", "around_message_id"):
            if key in args and type(args[key]) is int:
                safe[key] = args[key]
    return {"args_sha256": digest(args), "args_probe_token_sha256": probe_hashes(args),
            "safe_session_search_args": safe, "truncated_safe_arg_fields": truncated,
            "argument_logging_policy": "Bounded session_search selectors only; synthetic tokens redacted to hashes"}


def pre_tool_call(**payload):
    emit("pre_tool_call", payload, tool_name=payload.get("tool_name"),
         **argument_observation(payload.get("tool_name"), payload.get("args")),
         observation_source="Stock pre_tool_call after request middleware; no directive returned")
    # None means observe only: never block, approve, modify, or replace an argument.


def post_tool_call(**payload):
    result = payload.get("result")
    parsed = result
    if isinstance(result, str):
        try:
            parsed = json.loads(result)
        except (TypeError, ValueError):
            parsed = None
    parsed = parsed if isinstance(parsed, dict) else {}
    raw = result.encode("utf-8") if isinstance(result, str) else json.dumps(
        result, sort_keys=True, separators=(",", ":"), ensure_ascii=False, default=str).encode("utf-8")
    status = payload.get("status")
    error_type = payload.get("error_type")
    emit("post_tool_call", payload, tool_name=payload.get("tool_name"),
         **argument_observation(payload.get("tool_name"), payload.get("args")),
         result_sha256=hashlib.sha256(raw).hexdigest(), result_bytes=len(raw),
         result_hash_encoding="utf8" if isinstance(result, str) else "canonical_json",
         result_probe_token_sha256=probe_hashes(result),
         result_success_flag=parsed.get("success") if type(parsed.get("success")) is bool else None,
         result_error_present=bool(parsed.get("error")), result_error_sha256=digest(parsed.get("error")),
         status=status if status in {"ok", "error", "blocked", "cancelled", "timeout"} else None,
         status_sha256=digest(status),
         error_type=error_type if isinstance(error_type, str) and re.fullmatch(r"[a-z_]{1,64}", error_type) else None,
         error_message_sha256=digest(payload.get("error_message")), duration_ms=payload.get("duration_ms"),
         observation_source="Stock terminal post_tool_call result; result transformation/context persistence can follow")


def post_api_request(**payload):
    response = payload.get("response")
    message = payload.get("assistant_message")
    raw_message_present = message is not None
    if message is None:
        message = response.get("assistant_message") if isinstance(response, dict) else None
    def field(value, name):
        return value.get(name) if isinstance(value, dict) else getattr(value, name, None)
    calls = field(message, "tool_calls")
    observations = []
    for call in calls if isinstance(calls, (list, tuple)) else []:
        function = field(call, "function")
        args = field(function, "arguments")
        parsed = args
        if isinstance(args, str):
            try:
                parsed = json.loads(args)
            except (TypeError, ValueError):
                parsed = None
        observations.append({"tool_call_id": field(call, "id"), "tool_name": field(function, "name"),
                             "arguments_parsed": isinstance(parsed, dict),
                             "serialized_arguments_sha256": digest(args),
                             **argument_observation(field(function, "name"), parsed)})
    emit("post_api_request", payload, model=payload.get("model"), provider=payload.get("provider"),
         assistant_tool_call_count=payload.get("assistant_tool_call_count"), model_tool_calls=observations,
"}
